-- rule retired_assembly_in_use (row): parameterized; p1 boolean, p2 boolean
SELECT t."part_id" FROM "sxc_rules"."part" t WHERE (t."retired" IS NOT NULL AND t."retired" = CAST(:p1 AS boolean)) AND (EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL)) AND (EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e JOIN "sxc_rules"."part" n ON n."part_id" = e."parent_id" WHERE e."child_id" = t."part_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(:p2 AS boolean))));

-- rule retired_assembly_in_use: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_retired_assembly_in_use" AS
SELECT r.*, row_number() OVER (ORDER BY r."part_id" COLLATE "C" NULLS FIRST) AS ord FROM (SELECT t."part_id" FROM "sxc_rules"."part" t WHERE (t."retired" IS NOT NULL AND t."retired" = CAST(E'true' AS boolean)) AND (EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL)) AND (EXISTS (SELECT 1 FROM "sxc_rules"."bom_line" e JOIN "sxc_rules"."part" n ON n."part_id" = e."parent_id" WHERE e."child_id" = t."part_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(E'false' AS boolean))))) r;

-- example retired_assembly_in_use[0]: parameterized; 20 parameters
WITH "sxc_ex_part"("retired", "part_id") AS (VALUES (CAST(:p1 AS boolean), CAST(:p2 AS text)), (CAST(:p3 AS boolean), CAST(:p4 AS text)), (CAST(:p5 AS boolean), CAST(:p6 AS text)), (CAST(:p7 AS boolean), CAST(:p8 AS text))), "sxc_ex_bom_line"("parent_id", "child_id") AS (VALUES (CAST(:p9 AS text), CAST(:p10 AS text)), (CAST(:p11 AS text), CAST(:p12 AS text)), (CAST(:p13 AS text), CAST(:p14 AS text)), (CAST(:p15 AS text), CAST(:p16 AS text)), (CAST(:p17 AS text), CAST(:p18 AS text))) SELECT * FROM (SELECT t."part_id" FROM "sxc_ex_part" t WHERE (t."retired" IS NOT NULL AND t."retired" = CAST(:p19 AS boolean)) AND (EXISTS (SELECT 1 FROM "sxc_ex_bom_line" e WHERE e."parent_id" = t."part_id" AND e."child_id" IS NOT NULL)) AND (EXISTS (SELECT 1 FROM "sxc_ex_bom_line" e JOIN "sxc_ex_part" n ON n."part_id" = e."parent_id" WHERE e."child_id" = t."part_id" AND (n."retired" IS NOT NULL AND n."retired" = CAST(:p20 AS boolean))))) r;
